answer:
#include <stdio.h>

int main() {
    int a = 80;
    int b = 92;
    int c = 78;
    int sum = a + b + c;
    printf("合計 %d 点\n", sum);
    printf("平均 %.2f 点\n", (double)sum / 3);
    return 0;
}

